template.solver:
def solve(n):
    total = n * (n + 1) // 2
    if total % 2 != 0:
        return 0
    half = total // 2
    count = 0
    for a in range(1, n + 1):
        for b in range(a + 1, n + 1):
            for c in range(b + 1, n + 1):
                if a + b + c == half:
                    count += 1
    return count
